#!/usr/bin/env python3
"""Compare Yettel enrichment generated by GPT-5.4 mini vs GPT-4.1 mini.

The evaluation queries and gold evidence remain frozen.  This creates wholly
separate generation/vector/ranking caches for the GPT-4.1-mini arm and then
combines its three enrichment conditions with the shared baseline and the
three preserved GPT-5.4-mini conditions in a new report.
"""

from __future__ import annotations

import html
import json
import shutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "src"))
sys.path.insert(0, str(ROOT / "src" / "mhrag_vectoronly"))

from yettel_rag import run_experiments as Y  # noqa: E402

A = Y.A
C = Y.C
MODEL = "gpt-4.1-mini-2025-04-14"
OLD_MODEL = "gpt-5.4-mini"
SOURCE_DATA = ROOT / "data" / "processed" / "yettel_bg_experiments"
SOURCE_RESULTS = ROOT / "results" / "yettel_bg_experiments"
DATA = ROOT / "data" / "processed" / "yettel_bg_experiments_gpt41mini"
RESULTS = ROOT / "results" / "yettel_bg_experiments_gpt41mini"
REPORT = ROOT / "report" / "yettel_bg_generator_independence.html"
COMPARISON_METRICS = RESULTS / "generator_comparison_metrics.json"
for directory in (DATA, RESULTS, REPORT.parent):
    directory.mkdir(parents=True, exist_ok=True)


def configure() -> None:
    """Point imported pipeline modules at isolated GPT-4.1-mini artifacts."""
    A.MODEL = MODEL
    A.DATA = DATA
    A.RESULTS = RESULTS
    A.REPORT = REPORT
    A.CHUNKS_PATH = DATA / "chunks.jsonl"
    A.QUERIES_PATH = DATA / "queries.jsonl"
    A.SUMMARY_PATH = DATA / "summary.json"
    A.GEN_PATH = DATA / "adaptive_generations.jsonl"
    A.CHUNK_VECTORS = RESULTS / "chunk_vectors.json"
    A.QUERY_VECTORS = RESULTS / "query_vectors.json"
    A.BOUNDED_VECTORS = RESULTS / "bounded_question_vectors.json"
    A.UNBOUNDED_VECTORS = RESULTS / "unbounded_question_vectors.json"
    A.METRICS = RESULTS / "metrics.json"
    A.RANKINGS = RESULTS / "rankings.json"
    A.MAX_WORKERS = 24
    A.MAX_RETRIES = 6

    C.DATA = DATA
    C.RESULTS = RESULTS
    C.REPORT = REPORT
    C.ARTICLE_GENERATIONS = DATA / "article_question_generations.jsonl"
    C.ARTICLE_VECTORS = RESULTS / "article_question_vectors.json"
    C.ARTICLE_RANKINGS = RESULTS / "article_chunk_question_rankings.jsonl"
    C.MAX_WORKERS = 24

    # Freeze the exact prepared evaluation inputs and reuse only the two
    # generator-independent vector caches.  Question vectors remain separate.
    for name in ("chunks.jsonl", "queries.jsonl", "summary.json"):
        target = DATA / name
        if not target.exists():
            shutil.copyfile(SOURCE_DATA / name, target)
    for name in ("chunk_vectors.json", "query_vectors.json"):
        target = RESULTS / name
        if not target.exists():
            shutil.copyfile(SOURCE_RESULTS / name, target)


def label(condition: dict, model: str) -> dict:
    row = json.loads(json.dumps(condition))
    row["generator_model"] = model
    if row["condition"] != "Baseline":
        row["condition"] = f"{row['condition']} — {model}"
    return row


def render(payload: dict) -> None:
    keys = (
        "evidence_recall@1",
        "evidence_recall@5",
        "evidence_recall@10",
        "all_evidence_hit@5",
        "mrr@10",
    )
    baseline = payload["conditions"][0]["metrics"]
    rows = []
    for index, condition in enumerate(payload["conditions"]):
        q = condition["quality"]
        model = condition["generator_model"]
        combined = "chunk + whole" in condition["condition"].casefold()
        if index == 0:
            generation = "No generated questions"
            count = "0"
            retrieval = "Dense chunk-vector retrieval + BM25 chunk RRF"
        elif combined:
            generation = "5–20 per chunk + 5–20 per whole document"
            count = (
                f"{q['generated_questions']:,}<br><span>"
                f"{q['chunk_questions']:,} chunk + "
                f"{q['article_questions']:,} document</span>"
            )
            retrieval = (
                "Equal 1/3 chunk, chunk-question, document-question "
                "vector fusion + BM25 chunk RRF"
            )
        else:
            generation = html.escape(condition["question_rule"])
            count = f"{q['generated_questions']:,}"
            retrieval = "0.5/0.5 chunk-question vector fusion + BM25 chunk RRF"
        cells = []
        for key in keys:
            value = condition["metrics"][key]
            delta = value - baseline[key]
            delta_html = (
                ""
                if index == 0
                else (
                    f'<span class="delta {"up" if delta >= 0 else "down"}">'
                    f"{delta:+.3f}</span>"
                )
            )
            cells.append(f"<td><b>{value:.3f}</b>{delta_html}</td>")
        rows.append(
            f'<tr class="{"baseline" if index == 0 else ""}">'
            f'<td class="left"><b>{html.escape(condition["condition"])}</b></td>'
            f"<td>{html.escape(model) if model else 'None'}</td>"
            f'<td class="left">{generation}</td><td>{count}</td>'
            f"<td>{condition['stored_vectors']:,}</td>"
            f'<td class="left">{retrieval}</td>{"".join(cells)}</tr>'
        )
    p = payload["protocol"]
    REPORT.write_text(
        f"""<!doctype html><html><head><meta charset="utf-8">
<title>Yettel generator-independence experiment</title><style>
body{{background:#0f1319;color:#e6eaf0;font:14px/1.5 system-ui;padding:20px}}
main{{max-width:2200px;margin:auto}}table{{border-collapse:collapse;width:100%}}
th,td{{border:1px solid #29313d;padding:9px;text-align:center;vertical-align:top}}
th{{background:#161c25}}.left{{text-align:left}}.baseline{{background:#171d26}}
.note,span{{color:#9aa5b3;font-size:12px}}.delta{{display:block;font-weight:600}}
.up{{color:#63d89b}}.down{{color:#ff8080}}code{{overflow-wrap:anywhere}}
</style></head><body><main>
<h1>Yettel Bulgaria — enrichment-generator independence</h1>
<p class="note">Frozen evaluation: {p["eligible_queries"]} GPT-5.4-mini-generated evidence-bearing queries, {p["articles"]} documents, {p["chunks"]} chunks, canonical gold evidence. All rows share identical chunks, queries, Iris embeddings, Unicode Bulgarian BM25, RRF k=60, prompts, and question-allocation rules. Deltas are versus the shared baseline.</p>
<table><thead><tr><th class="left">Condition</th><th>Enrichment generator</th>
<th class="left">Question generation</th><th>Generated questions</th><th>Stored vectors</th>
<th class="left">Retrieval</th><th>Recall@1</th><th>Recall@5</th><th>Recall@10</th>
<th>Full-evidence@5</th><th>MRR@10</th></tr></thead>
<tbody>{"".join(rows)}</tbody></table>
<p class="note">Interpretation: agreement between GPT-5.4-mini and GPT-4.1-mini enrichment strengthens evidence that gains are not solely same-model stylistic coupling. The evaluation set remains synthetic, so this reduces rather than eliminates synthetic-benchmark bias.</p>
<p class="note">Machine-readable output: <code>results/yettel_bg_experiments_gpt41mini/generator_comparison_metrics.json</code></p>
</main></body></html>""",
        encoding="utf-8",
    )


def run() -> dict:
    configure()
    chunks, queries, summary = Y.prepare()
    generated = Y.generate_until_complete(chunks)
    print(f"[gpt41] chunks={len(chunks)} generated={len(generated)}", flush=True)
    new_adaptive = Y.adaptive_fast(chunks, queries, generated)
    articles = Y.article_inputs(chunks, generated)
    article_generated = C.generate_articles(articles)
    new_combined = Y.combined_fast(chunks, queries, generated, article_generated)

    old = json.loads((SOURCE_RESULTS / "metrics.json").read_text())
    old_baseline = next(
        row for row in old["conditions"] if row["condition"] == "Baseline"
    )
    old_enrichment = [
        row for row in old["conditions"] if row["condition"] != "Baseline"
    ]
    payload = {
        "protocol": {
            **summary,
            "evaluation_question_generator": OLD_MODEL,
            "enrichment_generators": [OLD_MODEL, MODEL],
            "controlled_variables": [
                "evaluation queries",
                "gold evidence",
                "chunks",
                "prompts",
                "question allocation",
                "Iris embeddings",
                "BM25",
                "RRF k=60",
            ],
        },
        "conditions": [label(old_baseline, "")]
        + [label(row, OLD_MODEL) for row in old_enrichment]
        + [label(row, MODEL) for row in new_adaptive + [new_combined]],
    }
    COMPARISON_METRICS.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    render(payload)
    print(json.dumps(payload, ensure_ascii=False, indent=2))
    return payload


if __name__ == "__main__":
    run()
